const bid = $('Load bid').first().json;
if (!bid.id) throw new Error('Bid not found');
const p = $input.all()
  .map((i) => Number(i.json.price))
  .filter((x) => Number.isFinite(x) && x > 0)
  .sort((a, b) => a - b);
const n = p.length;
const price = Number(bid.price);
const median = n ? (n % 2 ? p[(n - 1) / 2] : (p[n / 2 - 1] + p[n / 2]) / 2) : null;
let result = 'cleared';
let reason = null;
if (n < 5) {
  result = 'unverified';
  reason = `Only ${n} comparable prices, so this bid is not checked`;
} else if (price < 0.3 * median || price > 3 * median) {
  result = 'held';
  reason = `Similar ${bid.category} jobs went for about USD ${median.toFixed(0)}; `
    + `this bid is USD ${price} (${Math.round((price / median) * 100)}% of that)`;
}
return [{ json: { bidId: bid.id, jobId: bid.job_id, price, result, reason, median, n } }];
